import{_ as i,o as s,c as e,ae as t}from"./chunks/framework.BmsPYn1i.js";const c=JSON.parse('{"title":"フライトシミュレーターのサンプル","description":"","frontmatter":{},"headers":[],"relativePath":"SamplePrograms/FlightSimulator.md","filePath":"SamplePrograms/FlightSimulator.md"}'),l={name:"SamplePrograms/FlightSimulator.md"};function h(n,a,o,r,d,p){return s(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="フライトシミュレーターのサンプル" tabindex="-1">フライトシミュレーターのサンプル <a class="header-anchor" href="#フライトシミュレーターのサンプル" aria-label="Permalink to &quot;フライトシミュレーターのサンプル&quot;">​</a></h1><p>コウノトリを操縦して空を飛ぶゲームです。機体は自動で前進し続ける ので、ロール（左右の傾き）とピッチ（上下の向き）で進む方向を コントロールします。追いかけてくるオウムの敵を3羽撃ち落とすと クリア、飛んでくるブロックにぶつかってLIFEが0になると ゲームオーバーです。</p><p><strong><a href="../samples/FlightSimulator.html" target="_blank">▶ フライトシミュレーターを実行する</a></strong> （ソースを見るにはページを開いてブラウザの「ページのソースを表示」を 使うか、リンク先を保存してください）</p><h2 id="操作方法" tabindex="-1">操作方法 <a class="header-anchor" href="#操作方法" aria-label="Permalink to &quot;操作方法&quot;">​</a></h2><ul><li>PC — A/Dキーでロール（左右に傾ける）、W/Sキーでピッチ（機首の 上げ下げ）、Enterキーで弾丸発射。</li><li>スマホ — 左ジョイスティックでロールとピッチ、「R」ボタンで 弾丸発射。</li></ul><h2 id="このプログラムの特徴" tabindex="-1">このプログラムの特徴 <a class="header-anchor" href="#このプログラムの特徴" aria-label="Permalink to &quot;このプログラムの特徴&quot;">​</a></h2><h3 id="飛行機らしい操縦" tabindex="-1">飛行機らしい操縦 <a class="header-anchor" href="#飛行機らしい操縦" aria-label="Permalink to &quot;飛行機らしい操縦&quot;">​</a></h3><p>プレイヤー（<code>Stork.glb</code>のコウノトリ）は<code>SimplePhysics</code>モードの <code>rigidBody: &#39;kinematic&#39;</code>で、物理演算の影響（重力など）は受けずに プログラムから直接動かします。毎フレームの<code>update(dt)</code>は たった3行で、「自分の向き基準」の回転・移動メソッドを使うのが ポイントです。</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rollRightNow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">view.leftJoystick.x); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ロール(左右の傾き)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">turnDownNow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(view.leftJoystick.y);    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ピッチ(機首の上げ下げ)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">moveForwardNow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);                 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 常に前進</span></span></code></pre></div><p>地面との平行移動ではなく機体基準で回転するので、宙返りも 横転もできる飛行機らしい動きになります。</p><h3 id="カメラの「上」を機体に合わせる" tabindex="-1">カメラの「上」を機体に合わせる <a class="header-anchor" href="#カメラの「上」を機体に合わせる" aria-label="Permalink to &quot;カメラの「上」を機体に合わせる&quot;">​</a></h3><p>このサンプルで一番おもしろいところです。通常カメラの上方向は ワールドのY軸ですが、それだと機体が傾いたときにカメラが ついてきません。メインループで毎フレーム、デフォルトの上方向 ベクトルをプレイヤーの上方向に合わせることで、<code>Follow</code>モードの カメラが機体と一緒に傾くようになっています。</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a3.ObjectA3.defaultUpVector.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(player.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getUnitVecY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span></code></pre></div><p>ゲームが終わったら<code>(0,1,0)</code>に戻します。</p><h3 id="プレイヤーを追いかける敵" tabindex="-1">プレイヤーを追いかける敵 <a class="header-anchor" href="#プレイヤーを追いかける敵" aria-label="Permalink to &quot;プレイヤーを追いかける敵&quot;">​</a></h3><p>敵のオウム（<code>Parrot.glb</code>）は物理演算ではなく、毎フレーム 「プレイヤーの前方30m + ランダムなずれ（うろうろ成分）」に向かって 現在位置から3%ずつ近づく、という計算で動いています。単純な式ですが なめらかに追尾しているように見えます。</p><h3 id="障害物と弾丸" tabindex="-1">障害物と弾丸 <a class="header-anchor" href="#障害物と弾丸" aria-label="Permalink to &quot;障害物と弾丸&quot;">​</a></h3><ul><li>障害物のブロック（<code>ClearBlocks.a3</code>）はメインループ中に 100分の3の確率でプレイヤーの前方のランダムな位置に出現し、 ぶつかるとLIFEが減ります。</li><li>弾丸（<code>ball.glb</code>）は<code>kinematic</code>で毎フレーム前進し、一定時間で 消えます。敵に当たるとスコアが100点入ります。</li></ul><p>衝突の検出はすべて <a href="./../FeaturesIntroduction/CollisionDetection/">当たり判定</a>の <code>handleCollision()</code>で行い、<code>obj instanceof Bullet</code>のように 相手のクラスで処理を分けています。</p><h3 id="そのほか" tabindex="-1">そのほか <a class="header-anchor" href="#そのほか" aria-label="Permalink to &quot;そのほか&quot;">​</a></h3><ul><li>空を飛ぶゲームなので地面はなく、背景はAcerola3DのSkyBox （<code>SkyBox01.a3</code>）だけです。</li><li>LIFEとSCOREの表示はHTMLの要素に毎フレーム書き込んでいます。</li><li>BGM・効果音: <a href="https://maou.audio" target="_blank" rel="noreferrer">魔王魂</a></li></ul>`,21)])])}const g=i(l,[["render",h]]);export{c as __pageData,g as default};
